    "title": "Maplewright Transit Systems \u2014 a public-transit data platform serving real-time vehicle positions, route schedules, and rider alerts to regional transit agencies API",
    "served_at": "/openapi.json",
    "description": "OpenAPI 3.1 spec for the Maplewright Transit Systems \u2014 a public-transit data platform serving real-time vehicle positions, route schedules, and rider alerts to regional transit agencies API, inlined below. All endpoints are relative paths on the same host; construct requests with execute().",
    "document": {
      "openapi": "3.1.0",
      "info": {
        "title": "Maplewright Transit Systems \u2014 a public-transit data platform serving real-time vehicle positions, route schedules, and rider alerts to regional transit agencies API",
        "version": "1.0.0",
        "description": "TransitGraph API: a multi-tenant REST service that exposes GTFS-derived static schedules plus a streaming-ingested layer of live vehicle telemetry and service advisories. Years of mergers left overlapping resource families with near-identical names."
      },
      "servers": [
        {
          "url": "http://localhost:9001"
        }
      ],
      "paths": {
        "/openapi.json": {
          "get": {
            "summary": "OpenAPI spec doc",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/oauth/token": {
          "post": {
            "summary": "OAuth client_credentials",
            "security": [
              {
                "none": []
              }
            ]
          }
        },
        "/v3/routes": {
          "get": {
            "summary": "Canonical current route catalog",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/route-shapes": {
          "get": {
            "summary": "Geometry polylines only, not catalog",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/route-plans": {
          "get": {
            "summary": "Deprecated legacy route catalog",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/alerts": {
          "get": {
            "summary": "Internal ops alerts (not rider-facing)",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/advisories": {
          "get": {
            "summary": "Decommissioned advisories family",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/service-notices": {
          "get": {
            "summary": "Canonical rider-facing service notices",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/vehicles": {
          "get": {
            "summary": "Canonical live vehicle positions",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/vehicle-telemetry": {
          "get": {
            "summary": "Raw sensor diagnostics, not positions",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/fleet": {
          "get": {
            "summary": "Deprecated fleet roster",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/stops": {
          "get": {
            "summary": "Canonical stop directory",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/stop-times": {
          "get": {
            "summary": "Per-trip arrival times, not stop directory",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/agencies": {
          "get": {
            "summary": "Operating agencies list",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
